-- Pharmacy worklist samples for Phases 2 to 5 on the demo members.
-- `bun run seed` skips members already in the table, so these land here.
-- Each update runs once: it checks the sample isn't already there. Only
-- Barbara Klein's MAH (19405) is replaced as a whole, with the sample's
-- drugs and fills; the rest add to what each member has.
-- Generated from src/features/pharmacy-worklist/data/mock.js.

-- Phase 3: an Assessment and a fully documented outreach (Thomas Brooks).
UPDATE public.pharmacy_worklist_members SET call_history = '[{"id":"out-19408-2","date":"10/01/2026","time":"11:05 AM","type":"Call","contact":"Pharmacy","outcome":"Confirmed medication pickup date","result":"success","by":"Marcus Reyes","note":"Januvia 30-day picked up.","measures":["MAD"],"pickupDate":"09/30/2026","discussion":"Confirmed pickup at CVS #3301; asked about a 90-day supply.","barriers":["Cost Issue"],"transcript":"Pharmacist: Januvia 100 mg, 30 tablets, picked up yesterday at 4:10 PM. Copay was $47. Member asked whether a 90-day supply would cost less."}]'::jsonb || COALESCE(call_history, '[]'::jsonb)
  WHERE id = '19408' AND NOT COALESCE(call_history, '[]'::jsonb) @> '[{"id":"out-19408-2"}]'::jsonb;
UPDATE public.pharmacy_worklist_members SET call_history = '[{"id":"ver-19408-1","kind":"pharmacy-verification","locked":true,"date":"10/14/2026","time":"2:20 PM","mode":"Phone","action":"Telephonic","direction":"Outbound","contactOutcome":"Reached","party":"Pharmacy","contact":"CVS Pharmacy #3301","outcome":"Interventions logged","result":"failed","by":"Marcus Reyes","note":"Pharmacist will flag the Januvia copay for a generic switch.","measures":["MAD","MAH"],"picks":{"MAD":{"Cost or insurance coverage issues":true,"Pending":"Refill approval"},"MAH":{"Confirmed medication pickup date":true,"New 90/100DS conversion":true}},"outcomes":{"MAD":["Cost or insurance coverage issues","Pending: Refill approval"],"MAH":["Confirmed medication pickup date","New 90/100DS conversion"]}}]'::jsonb || COALESCE(call_history, '[]'::jsonb)
  WHERE id = '19408' AND NOT COALESCE(call_history, '[]'::jsonb) @> '[{"id":"ver-19408-1"}]'::jsonb;

-- Phase 4: intervention tasks with an overdue pharmacist review (Linda Washington).
UPDATE public.pharmacy_worklist_members SET intervention_log = '[{"date":"10/03/2026","by":"Marcus Reyes","note":"Interventions from the barrier template","source":"Intervention template","measures":{"MAC":{"barriers":["Side Effects"],"interventions":["Schedule MD Appointment/Labs","Pharmacist review"],"result":"Pending Pharmacist Review"}},"tasks":[{"code":"MAC","barrier":"Side Effects","intervention":"Pharmacist review","due":"10/06/2026","owner":"Nina Shah, PharmD","role":"pharmacist","taskId":null},{"code":"MAC","barrier":"Side Effects","intervention":"Schedule MD Appointment/Labs","due":"11/30/2026","owner":"Marcus Reyes","role":"coordinator","taskId":null}]}]'::jsonb || COALESCE(intervention_log, '[]'::jsonb)
  WHERE id = '19403' AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(intervention_log, '[]'::jsonb)) e WHERE e ? 'tasks');

