-- Phase 5: IVR pickup checks and a 90-day fill request.
UPDATE public.pharmacy_worklist_members SET measures = (
  SELECT jsonb_agg(CASE WHEN e->>'code' = 'MAH' THEN e || '{"ivrCheck":{"date":"11/12/2026","result":"Not picked up"}}'::jsonb ELSE e END ORDER BY i)
  FROM jsonb_array_elements(measures) WITH ORDINALITY AS a(e, i)
) WHERE id = '19402' AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(measures) e WHERE e->>'code' = 'MAH' AND e ? 'ivrCheck');
UPDATE public.pharmacy_worklist_members SET measures = (
  SELECT jsonb_agg(CASE WHEN e->>'code' = 'MAD' THEN e || '{"ivrCheck":{"date":"11/10/2026","result":"Picked up"}}'::jsonb ELSE e END ORDER BY i)
  FROM jsonb_array_elements(measures) WITH ORDINALITY AS a(e, i)
) WHERE id = '19401' AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(measures) e WHERE e->>'code' = 'MAD' AND e ? 'ivrCheck');
UPDATE public.pharmacy_worklist_members SET measures = (
  SELECT jsonb_agg(
    x || jsonb_build_object('medications', COALESCE((
      SELECT jsonb_agg(CASE WHEN d->>'id' = '19406-mad-3' THEN d || '{"longerFill":{"days":90,"status":"Requested","by":"Priya Natarajan","at":"2026-11-09T15:00:00.000Z"}}'::jsonb ELSE d END ORDER BY j)
      FROM jsonb_array_elements(x->'medications') WITH ORDINALITY AS b(d, j)
    ), x->'medications', '[]'::jsonb)) ORDER BY i)
  FROM jsonb_array_elements(measures) WITH ORDINALITY AS a(x, i)
) WHERE id = '19406' AND NOT EXISTS (
  SELECT 1 FROM jsonb_array_elements(measures) x, jsonb_array_elements(x->'medications') d WHERE d->>'id' = '19406-mad-3' AND d ? 'longerFill'
);
